import pandas as pd


def run(inputs: dict) -> dict:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Sort invoices per customer: oldest due_date first, tie-break by invoice_id
    invoices_sorted = invoices.sort_values(["customer_id", "due_date", "invoice_id"])
    # Sort payments per customer: earliest paid_ts first, tie-break by payment_id
    payments_sorted = payments.sort_values(["customer_id", "paid_ts", "payment_id"])

    # Track remaining open amount per invoice
    open_amt = dict(zip(invoices["invoice_id"], invoices["amount"].astype(float)))

    # Build ordered invoice id lists per customer
    cust_invoices = {}
    for cid, grp in invoices_sorted.groupby("customer_id"):
        cust_invoices[cid] = list(grp["invoice_id"])

    allocations = []
    credit = {}

    for cid, grp in payments_sorted.groupby("customer_id"):
        inv_list = cust_invoices.get(cid, [])
        for _, prow in grp.iterrows():
            left = float(prow["amount"])
            pid = prow["payment_id"]
            for inv_id in inv_list:
                if left <= 0:
                    break
                avail = open_amt[inv_id]
                if avail <= 0:
                    continue
                pay = min(left, avail)
                open_amt[inv_id] = avail - pay
                left -= pay
                allocations.append((pid, inv_id, pay))
                if left == 0:
                    break
            if left > 0:
                credit[cid] = credit.get(cid, 0.0) + left

    # Build invoice_status output
    status_rows = []
    for _, inv in invoices.iterrows():
        iid = inv["invoice_id"]
        orig = float(inv["amount"])
        rem = open_amt.get(iid, orig)

        # guard against floating point noise
        if abs(rem) < 1e-9:
            rem_val = 0.0
            status = "PAID"
        elif abs(rem - orig) < 1e-9:
            rem_val = orig
            status = "OPEN"
        else:
            rem_val = rem
            status = "PARTIAL"

        status_rows.append((iid, rem_val, status))

    invoice_status = pd.DataFrame(
        status_rows, columns=["invoice_id", "open_amount", "status"]
    )
    if not invoice_status.empty:
        invoice_status["invoice_id"] = invoice_status["invoice_id"].astype("int64")
        invoice_status["open_amount"] = invoice_status["open_amount"].astype("float64")
        invoice_status["status"] = invoice_status["status"].astype(object)

    allocations_df = pd.DataFrame(
        allocations, columns=["payment_id", "invoice_id", "applied_amount"]
    )
    if not allocations_df.empty:
        allocations_df["payment_id"] = allocations_df["payment_id"].astype("int64")
        allocations_df["invoice_id"] = allocations_df["invoice_id"].astype("int64")
        allocations_df["applied_amount"] = allocations_df["applied_amount"].astype("float64")
    else:
        allocations_df = pd.DataFrame(
            columns=["payment_id", "invoice_id", "applied_amount"]
        ).astype(
            {
                "payment_id": "int64",
                "invoice_id": "int64",
                "applied_amount": "float64",
            }
        )

    credit_rows = [(cid, amt) for cid, amt in credit.items() if amt > 1e-9]
    customer_credit = pd.DataFrame(
        credit_rows, columns=["customer_id", "unapplied_amount"]
    )
    if not customer_credit.empty:
        customer_credit["customer_id"] = customer_credit["customer_id"].astype("int64")
        customer_credit["unapplied_amount"] = customer_credit["unapplied_amount"].astype(
            "float64"
        )
    else:
        customer_credit = pd.DataFrame(
            columns=["customer_id", "unapplied_amount"]
        ).astype({"customer_id": "int64", "unapplied_amount": "float64"})

    return {
        "invoice_status": invoice_status,
        "allocations": allocations_df,
        "customer_credit": customer_credit,
    }
